{"cards": [{"node_code": "N_e243449dca51ed35", "definition": "研究铁路线路施工中道床（道碴）的铺设工艺、材料级配、压实标准及质量控制技术，涵盖有砟轨道道床的成型与整修。", "boundary": "本节点聚焦于“道床/道碴”这一特定结构层的施工。边界在于区分“铺碴”与“铺轨”（道床是轨道的基础，铺轨是钢轨与枕木的铺设，二者工序不同）、“铺碴”与“路基”（路基是土体基础，道床是碎石层）。若涉及无砟轨道，因无道碴铺设，相关混凝土道床施工通常归入铺轨或特殊轨道施工，不在此列。", "includes": ["道碴材料选择、筛分与级配要求", "道床铺设方法（如机械铺碴、人工整理）及厚度、边坡控制", "道床捣固、起拨道及施工期道床状态检测"], "excludes": ["钢轨、轨枕的铺设与连接（归入铺轨工程）", "路基土石方填筑与压实（归入土石方工程）", "无砟轨道混凝土道床施工（视具体分类归入铺轨或特殊轨道）"], "sibling_distinctions": [{"other_code": "N_08c449471e1c37ee", "rule": "区分依据为施工对象：铺碴工程针对道床碎石层；铺轨工程针对钢轨、轨枕及扣件系统。"}, {"other_code": "N_e005be056013ae66", "rule": "区分依据为结构层次：铺碴工程位于路基之上、轨道之下；土石方工程针对路基本体及边坡。"}], "cross_boundary_rule": "若内容涉及“道床与路基结合部处理”，若侧重道床铺设工艺，主挂载本节点；若侧重路基沉降控制，可关联土石方工程。"}, {"node_code": "N_08c449471e1c37ee", "definition": "研究铁路线路施工中钢轨、轨枕及扣件系统的铺设工艺、几何尺寸控制、焊接技术及轨道结构成型的质量管理。", "boundary": "本节点聚焦于“轨道结构”（钢轨+轨枕+扣件）的施工。边界在于区分“铺轨”与“铺碴”（铺轨在道床之上）、“铺轨”与“线路设计”（设计定参数，施工定实施）。若涉及长钢轨铺设，包含牵引、焊接、应力放散等工艺。无砟轨道的轨道板铺设也归入此类。", "includes": ["钢轨铺设（含长钢轨牵引、焊接、应力调整）及轨枕安装", "扣件系统安装、轨道几何尺寸（轨距、水平、高低）调整", "无砟轨道轨道板铺设及精调技术"], "excludes": ["道床（道碴）的铺设与整理（归入铺碴工程）", "路基工程及桥隧主体结构施工", "轨道运营期的养护维修与病害处理"], "sibling_distinctions": [{"other_code": "N_e243449dca51ed35", "rule": "区分依据为施工对象：铺轨工程针对钢轨、轨枕及扣件；铺碴工程针对道床碎石层。"}, {"other_code": "N_942e6116aca6bf09", "rule": "区分依据为内容属性：铺轨工程关注工艺与质量标准；施工机具关注用于铺轨的设备本身及其性能。"}], "cross_boundary_rule": "若内容涉及“铺轨施工中的测量技术”，若侧重轨道几何控制，主挂载本节点；若侧重测量仪器原理，可关联测量类，但施工应用归本节点。"}, {"node_code": "N_942e6116aca6bf09", "definition": "研究铁路线路施工中各类专用机械、工具的性能、选型、操作规范及施工机械化作业的组织与效率提升技术。", "boundary": "本节点聚焦于“施工装备”与“机械化作业”。边界在于区分“机具”与“工艺”（机具是工具，工艺是方法）、“机具”与“车辆”（施工机械非运营车辆）。涵盖铺轨机、捣固车、挖掘机等设备的施工应用。若涉及设备研发制造，归入机械工程；此处侧重施工应用。", "includes": ["铁路施工专用机械（如铺轨机、长钢轨运输车、捣固车）的性能与操作", "施工机具的选型、配置及机械化作业流程优化", "施工设备的安全使用、维护保养及故障排除"], "excludes": ["铁路运营车辆（机车、客车、货车）的设计与制造", "通用工程机械（如非铁路专用的挖掘机）的基础理论研究", "施工材料本身的性能研究"], "sibling_distinctions": [{"other_code": "N_08c449471e1c37ee", "rule": "区分依据为关注点：本节点关注施工所用的机械设备；铺轨工程关注轨道结构的铺设工艺与质量。"}, {"other_code": "N_3b82071d2dd7b1de", "rule": "区分依据为内容性质：本节点关注现有机具的应用；施工新技术关注工艺方法的创新与改进。"}], "cross_boundary_rule": "若内容涉及“新型铺轨机的研发”，若侧重施工应用效果，主挂载本节点；若侧重机械结构设计，可关联机械工程，但施工语境下归本节点。"}]}
